import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw=new PrintWriter(System.out);
        int T=1;
        for(int t=0;t<T;t++){
            Solution s=new Solution(pw,br);
            s.process(T,t);
        }
        pw.close();
    }
    static class Solution {
        PrintWriter out;
        BufferedReader br;
        public Solution(PrintWriter out, BufferedReader br) {
            this.out=out;
            this.br=br;
        }
        public void process(int all, int testcase) throws IOException {
            int n=Integer.parseInt(br.readLine());
            int mod=Integer.parseInt(br.readLine());
            long[][] dp=new long[n][n*n+5];
            dp[0][0]=1;
            for(int i=1;i<n;i++){
                for(int j=0;j<dp[0].length;j++){
                    for(int cnt=0;cnt<=i;cnt++){
                        if(j-cnt>=0){
                            dp[i][j]+=dp[i-1][j-cnt];
                            dp[i][j]%=mod;
                        }
                    }
                }
            }
            long[][] sums=new long[dp.length][dp[0].length];
            for(int i=0;i<dp.length;i++){
                long sum=0;
                for(int j=0;j<dp[0].length;j++){
                    sum+=dp[i][j];
                    sum%=mod;
                    sums[i][j]=sum;
                }
            }
            long[] fact=new long[501*501];
            fact[0]=1;fact[1]=1;
            for(int i=2;i<fact.length;i++){
                fact[i]=(fact[i-1]*i)%mod;
            }
            long[][] ncr=new long[501][501];
            ncr[0][0]=1;
            for(int i=1;i<ncr.length;i++){
                ncr[i][0]=1;
                for(int j=1;j<ncr[0].length;j++){
                    ncr[i][j]=(ncr[i-1][j]+ncr[i-1][j-1])%mod;
                }
            }
            long res=0;
            for(int i=n-2;i>=0;i--){
                int cnt=n-i;
                int pre=n-cnt;
                long com=(ncr[n][pre]*fact[pre])%mod;
                long sum=0;
                for(int dif=1;dif<cnt;dif++){
                    for(int inv=dif;inv<dp[0].length;inv++){
                        if(dp[cnt-1][inv]==0)break;
                        if(inv-dif-1<0)continue;
                        long x=dp[cnt-2][inv];
                        long y=sums[cnt-2][inv-dif-1];
                        x=(x*y)%mod;
                        sum+=(x*(cnt-dif))%mod;
                        sum%=mod;
                    }
                }
                res+=(sum*com)%mod;
                res%=mod;
            }
            out.println(res%mod);
        }
    }
}
